// Package render produces the file contents for dnsmasq .conf and Caddy
// .caddy outputs (design §4).
package render

import (
	"fmt"
	"strings"
	"text/template"

	"hemma/internal/config"
)

// Header marks generated files. Identical across both output types.
const Header = "# GENERATED by hemma — do not edit. Source: services.yaml"

// CaddyImportFile is the content of hemma.generated.caddy — the single file
// every host's Caddyfile should import. Order matters: the auth snippet
// and tls snippets must be defined before the site blocks that reference them.
const CaddyImportFile = Header + "\n" +
	"import " + AuthSnippetFilename + "\n" +
	"import tls/*.caddy\n" +
	"import sites/*.caddy\n"

// CaddyImportFilename is the name of the generated import file.
const CaddyImportFilename = "hemma.generated.caddy"

// AuthSnippetName is the Caddy snippet name every protected site imports. It is
// "auth" — the concept, never a provider name — so swapping the
// backing provider is a content change in one file, not a rename everywhere.
const AuthSnippetName = "auth"

// AuthSnippetFilename is the generated file holding the (auth) snippet. It sits
// directly in caddy/data/ (a sibling of hemma.generated.caddy), so it is not
// picked up by the sites/*.caddy or tls/*.caddy globs and must be imported by
// name — which CaddyImportFile does, before the site blocks.
const AuthSnippetFilename = "hemma.auth.generated.caddy"

// AuthServiceToken is the placeholder defaults.auth_snippet writes in place of
// the forward-auth target, substituted per host by AuthSnippet. Deliberately
// NOT Caddy's own {$VAR} env syntax: if substitution were ever missed, Caddy
// would silently expand {$...} to empty and dial nothing, whereas this token
// survives into `caddy validate` as an obvious unresolvable upstream.
const AuthServiceToken = "@@AUTH_SERVICE@@"

// AuthSnippet renders the (auth) snippet file. When body is non-empty it is the
// user-provided auth directive(s) from defaults.auth_snippet, with every
// AuthServiceToken replaced by authService — the forward-auth target resolved
// for THIS host (§4.7): the auth service's own backend when it runs here (a
// direct container hop), its public FQDN when it lives on another host. The
// same-host case must not go via the FQDN: that hairpins out and back through
// the host's own NAT, arriving from the bridge gateway rather than a trusted
// peer, which resets the client IP exactly as §4.7 describes for a cross-host
// hop — except no trusted_proxies entry can fix it without trusting the whole
// NAT path.
//
// When body is empty, OR body needs a target that could not be resolved (no
// auth_service, or it names an unknown service), an empty (auth) {} stub is
// emitted. Every site block imports (auth) unconditionally, so the empty stub
// is a deliberate no-op: it lets a service opt in via `import auth` while
// global auth is off, and lets auth be turned on/off by changing this one
// file's content rather than rewriting sites. Emitting the stub rather than a
// half-substituted directive keeps a broken forward_auth out of a live Caddy —
// `import auth` then gates nothing, which `caddy validate` accepts, so callers
// must report the unresolved target rather than relying on a load failure.
func AuthSnippet(body, authService string) string {
	inner := strings.TrimRight(body, "\n")
	if inner == "" || (strings.Contains(inner, AuthServiceToken) && authService == "") {
		return fmt.Sprintf("%s\n(%s) {\n}\n", Header, AuthSnippetName)
	}
	inner = strings.ReplaceAll(inner, AuthServiceToken, authService)
	// Indent each line of the provided body one tab into the snippet block.
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n(%s) {\n", Header, AuthSnippetName)
	for _, line := range strings.Split(inner, "\n") {
		if line == "" {
			b.WriteString("\n")
			continue
		}
		b.WriteString("\t")
		b.WriteString(line)
		b.WriteString("\n")
	}
	b.WriteString("}\n")
	return b.String()
}

// TLSSnippetName derives the Caddy snippet name for a domain: tls_ followed by
// the domain with dots replaced by underscores (e.g. example.com ->
// tls_example_com). Deterministic and collision-free across TLDs.
func TLSSnippetName(domain string) string {
	return "tls_" + strings.ReplaceAll(domain, ".", "_")
}

// TLSSnippet renders the Caddy (tls_<domain>) snippet that points at the
// domain's wildcard cert. The cert path convention is fixed:
// /etc/caddy/certs/<domain>/{fullchain.cer,privkey.key} (design §4.3). The
// tool generates this so a domain needs no hand-written Caddyfile snippet.
func TLSSnippet(domain string) string {
	return fmt.Sprintf(
		"%s\n(%s) {\n\ttls /etc/caddy/certs/%s/fullchain.cer /etc/caddy/certs/%s/privkey.key\n}\n",
		Header, TLSSnippetName(domain), domain, domain)
}

// DNSRecord renders the dnsmasq directives for a service.
//
//   - local=/<fqdn>/ makes dnsmasq authoritative for the WHOLE name, so query
//     types with no local record — notably the HTTPS/SVCB (type 65) record —
//     return NODATA instead of being forwarded upstream and cached. Required:
//     address= alone only covers A/AAAA; without local=, dnsmasq forwards the
//     HTTPS query to Cloudflare, and SVCB-aware clients (Safari, Chrome/Edge)
//     follow its public endpoint hint, bypassing split-horizon. (Verified: with
//     local= type 65 is NODATA; without it, type 65 is the cached Cloudflare
//     record.)
//   - the A record points at hostIP (the host that RUNS the service).
//   - address=/<fqdn>/:: suppresses the public AAAA; :: (unspecified) is
//     correct, ::1 (loopback) is a bug (design §4.1).
func DNSRecord(fqdn, hostIP string) string {
	return fmt.Sprintf("%s\nlocal=/%s/\naddress=/%s/%s\naddress=/%s/::\n",
		Header, fqdn, fqdn, hostIP, fqdn)
}

// CaddySite renders the Caddy site block for a service. tlsImport is the
// snippet name (e.g. tls_example_com); backend is emitted verbatim as the
// reverse_proxy upstream (design §4.2).
//
// The auth mode decides what gate (if any) is emitted before reverse_proxy:
//   - AuthForward imports the (auth) snippet before proxying — every request
//     goes through the forward-auth check. auth.bypass_paths are deliberately NOT
//     rendered here: the auth provider's generated bypass rules (design §4.5,
//     auth.AccessControl) are the single policy engine, so Caddy emits no
//     per-path branches that could drift from them.
//   - AuthOIDC, AuthExternal and AuthNone all render a PLAIN reverse_proxy (no
//     import auth) — byte-identical output for the three. Forward is the only
//     mode gated here because it is the only one where hemma IS the gate: an
//     oidc app runs the flow itself, an external one is gated by something hemma
//     cannot see (the app's own login, an API token, an edge proxy such as
//     Cloudflare Access), and none has no gate at all.
//     Identical output is precisely why the mode is still recorded: it survives
//     in services.yaml and in `list`, so a protected service is never
//     indistinguishable from an unprotected one just because their Caddy blocks
//     match. (config.AuthMode.UsesProvider draws the other line — which modes
//     Authelia validates — and puts oidc with forward, not with external.)
//
// The gate is decided by config.Service.GateScope (§4.9), not by the mode alone:
// Caddy asks the provider only on a horizon where it has something to check.
// GateAll is the forward shape above; GateOutside scopes the same (auth) import
// to requests from outside localNetworks with a named matcher and a route — the
// user-supplied snippet is scoped, never rewritten — so a local request never
// reaches the provider (an oidc service with forward_gate, or forward with a
// local bypass); GateNone is the plain proxy.
//
// authBackend is orthogonal to the mode: when true (this service is the
// forward-auth portal) the reverse_proxy preserves the inbound X-Forwarded-Host
// so post-login redirects target the original service, not the portal.
//
// A service with no extra_directives is rendered by this function; see
// CaddySiteWithDirectives for one that has it.
func CaddySite(fqdn, tlsImport, backend string, gate config.GateScope, localNetworks []string, authBackend bool) string {
	return CaddySiteWithDirectives(fqdn, tlsImport, backend, gate, localNetworks, authBackend, SiteDirectives{})
}

// CaddySiteWithDirectives is CaddySite plus the service's extra_directives
// (config.Service.ExtraDirectives). The whole site is one template (siteTemplate), and
// the extra directives go into its one slot: inside a `route { }` block after the gate
// and before the reverse_proxy line, under a comment naming the source file so a
// reader of the generated site knows where to edit.
//
// The route block is the point. Caddy runs bare directives in its own fixed order, not
// the order they are written in, and that order puts rewrite, uri and header BEFORE the
// auth gate (forward_auth): a bare `uri` rule would change the path the gate judges.
// Inside a route block the directives run in the order written, and the block itself
// runs after the gate — in both gate shapes, and the same on a service without a gate,
// so a rule means the same thing whether or not the service later gets one. Only
// handler directives are allowed in a route block; Caddy itself refuses a site-level
// one (log, tls, ...) there, which `hemma apply` meets at `caddy validate`, before any
// reload.
//
// The zero SiteDirectives (or a blank body) adds nothing, so a service without one
// renders byte-identically to CaddySite.
func CaddySiteWithDirectives(fqdn, tlsImport, backend string, gate config.GateScope, localNetworks []string, authBackend bool, extra SiteDirectives) string {
	// The forward-auth backend (e.g. an Authelia portal) must preserve the inbound
	// X-Forwarded-Host through the reverse_proxy. When a protected service's
	// auth check hits this backend, Caddy's outer hop already set
	// X-Forwarded-Host to the *original* service host; a plain reverse_proxy
	// would reset it to this block's host (the auth domain), making Authelia
	// treat itself as the target and loop the post-login redirect. Preserving it
	// is safe: the value is whatever the trusted outer Caddy hop computed, not
	// anything a client can spoof.
	proxyLine := fmt.Sprintf("reverse_proxy %s", backend)
	if authBackend {
		proxyLine = fmt.Sprintf("reverse_proxy %s {\n\t\theader_up X-Forwarded-Host {header.X-Forwarded-Host}\n\t}", backend)
	}

	// AuthForward: one uniform shape — import auth, then proxy. No handle
	// wrappers: with a single branch they add nothing, and per-path public
	// branches are the auth provider's job now.
	data := siteData{
		Header: Header, FQDN: fqdn, TLS: tlsImport, Proxy: proxyLine,
		AuthSnippet: AuthSnippetName, OutsideMatcher: OutsideMatcher, Networks: strings.Join(localNetworks, " "),
		// GateOutside with no local networks has nobody to leave out: everyone is asked (GateScope already says GateAll then;
		// this is the backstop).
		GateAll:     gate == config.GateAll || (gate == config.GateOutside && len(localNetworks) == 0),
		GateOutside: gate == config.GateOutside && len(localNetworks) > 0,
		Extras:      extra.indented(), ExtrasPath: extra.Path,
	}
	var b strings.Builder
	// Cannot fail: the template and siteData are fixed in this file and every shape is rendered in the tests, so an error here is
	// a programming mistake caught before release, not something a services.yaml can cause.
	if err := siteTmpl.Execute(&b, data); err != nil {
		panic("render: site template: " + err.Error())
	}
	return b.String()
}

// siteTemplate is the whole shape of a service's Caddy site block, in one place: the TLS import, then the gate (none, everyone, or
// only requests from outside the local networks), then the service's extra directives inside a route block, then the proxy.
// The extra directives can only land in that slot, so they can only run after the gate. It is a constant: nothing at run time,
// and no services.yaml, can change it. The extra directives and every other field are DATA handed to Execute, never parsed as
// template text, so a `{{` in someone's rules means nothing here.
//
// Whitespace: `{{-` swallows the newline before an action, so each optional part starts its own line itself.
const siteTemplate = `{{.Header}}
{{.FQDN}} {
	import {{.TLS}}
{{- if .GateAll}}
	import {{.AuthSnippet}}
{{- else if .GateOutside}}
	@{{.OutsideMatcher}} not client_ip {{.Networks}}
	route @{{.OutsideMatcher}} {
		import {{.AuthSnippet}}
	}
{{- end}}
{{- if .Extras}}
	# extra_directives: {{.ExtrasPath}} (edit that file, not this one)
	route {
{{.Extras}}
	}
{{- end}}
	{{.Proxy}}
}
`

// siteTmpl is siteTemplate parsed once. template.Must panics at start-up if the text above is malformed.
var siteTmpl = template.Must(template.New("site").Parse(siteTemplate))

// siteData is everything siteTemplate refers to. Extras arrives already indented for its place inside the route block.
type siteData struct {
	Header, FQDN, TLS, Proxy string
	AuthSnippet              string
	OutsideMatcher, Networks string
	GateAll, GateOutside     bool
	Extras, ExtrasPath       string
}

// SiteDirectives is a service's extra_directives: the repo-relative Path it was read from
// and the file's Body. The zero value means none.
type SiteDirectives struct {
	Path string
	Body string
}

// indented renders the body for its place inside the route block of a site block: each non-empty line indented two tabs (one for
// the site block, one for the route block; a line's own indentation stays on top, and blank lines stay empty, as in AuthSnippet),
// joined by newlines with no trailing one. Empty when the body is blank. Trailing whitespace on a line is dropped, and CRLF
// becomes LF, so an editor's stray spaces never make the generated file differ from run to run.
func (e SiteDirectives) indented() string {
	inner := strings.TrimRight(e.Body, " \t\r\n")
	if strings.TrimSpace(inner) == "" {
		return ""
	}
	lines := strings.Split(strings.ReplaceAll(inner, "\r\n", "\n"), "\n")
	for i, line := range lines {
		line = strings.TrimRight(line, " \t")
		if line != "" {
			line = "\t\t" + line
		}
		lines[i] = line
	}
	return strings.Join(lines, "\n")
}

// OutsideMatcher names the matcher for requests from outside defaults.local_networks in a GateOutside site.
const OutsideMatcher = "hemma_outside"

// TrustedProxiesFilename is the generated file holding the trusted_proxies
// and client_ip_headers directives for one host's Caddy. It sits directly in
// caddy/data/ (a sibling of hemma.generated.caddy and
// hemma.auth.generated.caddy), so it is not picked up by any glob import and
// must be imported by name — inside the operator's own global `servers {}`
// options block, since Caddy only allows trusted_proxies there (never in a
// site block). hemma cannot write that block itself when it also carries
// hand-maintained options (e.g. `debug`), so this one import line is a
// manual, one-time step per host; `hemma doctor` only checks for its
// presence anywhere in the Caddyfile, not its placement inside servers {}.
const TrustedProxiesFilename = "hemma.trusted_proxies.generated.caddy"

// TrustedProxiesSnippet renders one host's trusted_proxies file: every IP in
// ips (already deduped/sorted by the caller) as a `trusted_proxies static`
// list, plus a fixed client_ip_headers line covering both a Cloudflare
// Tunnel's real-client-IP header and the standard X-Forwarded-For chain.
// ips is always non-empty in practice (every declared host's IP is trusted
// automatically — see plan.planTrustedProxies), but an empty list still
// renders a header-only, functionally inert file rather than being omitted,
// matching AuthSnippet's always-present-even-when-inert convention.
func TrustedProxiesSnippet(ips []string) string {
	if len(ips) == 0 {
		return Header + "\n"
	}
	return fmt.Sprintf("%s\ntrusted_proxies static %s\nclient_ip_headers Cf-Connecting-Ip X-Forwarded-For\n",
		Header, strings.Join(ips, " "))
}

// CloudflaredConfigFilename is the file hemma writes wholesale into each
// host's configured tunnel directory (defaults.tunnel_dir — one repo-wide
// path, required before any public: true service can plan), replacing what
// used to be a hand-maintained near-empty stub plus per-service
// cloudflare.io/* compose labels. cloudflared-wrapper mounts this directory
// as /etc/cloudflared and reads config.yml as its base config on every start.
const CloudflaredConfigFilename = "config.yml"

// CloudflaredIngressEntry is one public service's tunnel ingress rule.
type CloudflaredIngressEntry struct {
	// Hostname is the public FQDN cloudflared routes.
	Hostname string
	// Backend is the ingress "service" value. Always routed through Caddy
	// (https://caddy:443) — no per-service bypass: the redirect-loop concern
	// that once justified an auth_service exemption lives in the auth MODE,
	// not in "does traffic pass through Caddy", and planService already
	// refuses to let the auth_service carry any auth mode at all, so its
	// Caddy site never imports (auth) regardless of how public traffic
	// reaches it. cloudflared-wrapper's writeMergedConfig injects the
	// originServerName/httpHostHeader SNI+Host fix for every https:// ingress
	// entry regardless of where it came from (a label OR a raw config.yml
	// entry, as of cloudflared-wrapper commit c0c68cd) — hemma does not need
	// to (and deliberately does not) write that block itself.
	Backend string
}

// CloudflaredConfig renders config.yml for one host: one ingress rule per
// public entry, terminated by the mandatory catch-all. hemma writes this file
// WHOLESALE — no merge with anything hand-written, since there is no longer
// any hand-editing of a host's cloudflared config (design §12: hemma is the
// sole author, same posture as a Caddy site file). The catch-all is written
// explicitly rather than relied upon from cloudflared-wrapper's own missing-
// catch-all fallback, since ingress match order matters (it must be last) and
// a generator should not depend on a consumer's forgiveness for something it
// can trivially guarantee itself. Entries are rendered in the order given;
// callers sort by hostname for a stable diff.
func CloudflaredConfig(entries []CloudflaredIngressEntry) string {
	var b strings.Builder
	b.WriteString(Header)
	b.WriteString("\ningress:\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "  - hostname: %s\n    service: %s\n", e.Hostname, e.Backend)
	}
	b.WriteString("  - service: http_status:404\n")
	return b.String()
}
